// One project-scoped draft shared by all three input tabs.
const requestDrafts = {};
function requestDraft(){return requestDrafts[selected] ||= {tab:'text',files:[],meetingType:'recording',entries:[],running:false,timer:null,link:'',notes:current().meeting||''};}
function contextTab(tab){captureReq();requestDraft().tab=tab;render();}
function contextMeetingType(type){captureReq();requestDraft().meetingType=type;render();}
function contextTranscripts(d){return '<div class="bilingual-page">'+[['English',1],['日本語',2]].map(([title,col])=>'<section class="panel"><div class="panel-title"><h3>'+title+'</h3></div><div class="transcript-feed">'+(d.entries.length?d.entries.map((row,i)=>'<article class="speaker-entry"><div><strong>'+esc(row[0])+'</strong><time>00:'+String(i*8).padStart(2,'0')+'</time></div><p>'+esc(row[col])+'</p></article>').join(''):'<p class="sub">Transcript will appear here.</p>')+'</div></section>').join('')+'</div>';}
function contextMeeting(){const d=requestDraft();return '<div class="context-meeting-tabs" role="tablist">'+[['recording','Record a meeting'],['google','Zoom meeting']].map(([key,title])=>'<button role="tab" aria-selected="'+(d.meetingType===key)+'" class="'+(d.meetingType===key?'primary':'')+'" onclick="contextMeetingType(\''+key+'\')">'+title+'</button>').join('')+'</div>'+(d.meetingType==='google'?'<label class="field">Meeting link<input value="'+esc(d.link)+'" oninput="requestDraft().link=this.value" placeholder="https://zoom.us/j/…"></label><p class="sub">Zoom connection is not available. Preview the sample transcript below.</p>':'<p class="sub">Demo recording uses sample speaker-separated text. No audio is captured.</p>')+'<div class="context-meeting-actions"><span class="badge '+(d.running?'blue':'gray')+'">'+(d.running?'● Recording preview in progress':'Meeting context')+'</span>'+button(d.running?'Stop preview':'Start recording preview →',d.running?'stopContextMeeting()':'setupContextMeeting()',!d.running)+'</div>'+contextTranscripts(d)+'<label class="field">Meeting notes or transcript<textarea id="meeting" oninput="requestDraft().notes=this.value;current().meeting=this.value" placeholder="Paste a transcript or add meeting notes">'+esc(d.notes)+'</textarea></label>';}
blueprintPageRoutes.request=function(){if(!selected)return missingProject();const d=requestDraft(),r=current();return appNav()+bpHeading('New requirement request','Combine text, documents and meeting context. Use any one source or all three.')+'<section class="panel combined-request"><div class="context-tabs" role="tablist">'+[['text','Text input',r.brief.trim()?'Added':'Optional'],['upload','Upload documents',d.files.length?d.files.length+' files':'Optional'],['meeting','Meeting recording',d.running?'● Recording':d.entries.length||d.notes?'Added':'Optional']].map(([key,title,status])=>'<button role="tab" aria-selected="'+(d.tab===key)+'" class="'+(d.tab===key?'active':'')+'" onclick="contextTab(\''+key+'\')"><strong>'+title+'</strong><small>'+status+'</small></button>').join('')+'</div><div class="context-content" role="tabpanel">'+(d.tab==='text'?'<label class="field">Describe your product idea, requirements, or business needs<textarea id="brief" oninput="current().brief=this.value" placeholder="Add your requirements and notes">'+esc(r.brief)+'</textarea></label>':d.tab==='upload'?'<label class="upload-zone"><b>Add supporting files</b><span>Choose multiple files · Up to 20 MB each</span><input type="file" multiple onchange="addContextFiles(this)"></label><p class="sub">Text, Markdown, CSV, JSON and Excel content can be read in this preview. Other files are kept as attachments; paste their relevant text in Text input.</p><div class="context-file-list">'+d.files.map((f,i)=>'<article><div><strong>'+esc(f.name)+'</strong><small>'+esc(f.status)+'</small></div><button aria-label="Remove '+esc(f.name)+'" onclick="requestDraft().files.splice('+i+',1);render()">Remove</button></article>').join('')+'</div>':contextMeeting())+'</div><div class="context-summary"><span>All added sources will be combined. Switching tabs keeps your data in this session.</span><button class="primary" '+(r.approved?'disabled':'')+' onclick="continueRequest()">Continue to SRS →</button></div></section>';};
async function addContextFiles(input){const id=selected,d=requestDraft();for(const file of input.files){if(file.size>20*1024*1024){toast(file.name+': maximum size is 20 MB.');continue;}const item={name:file.name,file,text:'',status:'Reading…'};d.files.push(item);try{if(/\.(txt|md|csv|json|log)$/i.test(file.name)){item.text=await file.text();item.status=item.text.trim()?'Content ready':'Empty file';}else if(/\.(xlsx|xls)$/i.test(file.name)){const book=XLSX.read(await file.arrayBuffer(),{type:'array'});item.text=book.SheetNames.map(name=>name+'\n'+XLSX.utils.sheet_to_csv(book.Sheets[name])).join('\n\n');item.status='Content ready';}else item.status='Attachment only · Text extraction unavailable';}catch(e){item.status='Could not read content · Attachment retained';}}if(selected===id&&screen==='request'){captureReq();render();}}
function setupContextMeeting(){const box=document.getElementById('modal');box.className='recording-dialog';box.innerHTML='<div class="record-heading"><div><h2>Recording setup</h2><p>Sample bilingual transcript · No audio captured</p></div></div><div class="form"><p>You can switch to Text input or Upload documents while the preview runs.</p></div><div class="form-footer"><button onclick="document.getElementById(\'modal\').close()">Cancel</button><button class="primary" onclick="startContextMeeting()">Start recording preview →</button></div>';box.showModal();}
function startContextMeeting(){document.getElementById('modal').close();const id=selected,d=requestDraft();if(d.running)return;d.running=true;let index=0;d.timer=setInterval(()=>{d.entries.push([...jpMeeting[index++]]);if(index>=jpMeeting.length){clearInterval(d.timer);d.running=false;}if(selected===id&&screen==='request'&&d.tab==='meeting'){captureReq();render();}},1800);render();}
function stopContextMeeting(){const d=requestDraft();clearInterval(d.timer);d.running=false;captureReq();render();}
function combinedRequestContext(r,d){return [r.brief.trim()? 'Project brief\n'+r.brief.trim():'',...d.files.filter(f=>f.text.trim()).map(f=>'Document: '+f.name+'\n'+f.text.trim()),d.notes.trim()?'Meeting notes\n'+d.notes.trim():'',d.entries.length?'Meeting transcript · Demo\n'+d.entries.map(row=>row[0]+': '+row[1]+'\n'+row[2]).join('\n\n'):''].filter(Boolean).join('\n\n');}
continueRequest=function(){captureReq();const id=selected,r=current(),d=requestDraft();if(r.approved)return navigate('srs');if(d.files.some(f=>f.status==='Reading…'))return toast('Please wait for your files to finish reading.');const content=combinedRequestContext(r,d);if(!content.trim())return toast('Add text, readable document content or a meeting transcript first.');clearInterval(d.timer);d.running=false;if(d.google){clearInterval(d.google.timer);d.google.playing=false;}r.combinedContext=content;r.meeting=[d.notes,...d.entries.map(row=>row[0]+': '+row[1]+'\n'+row[2])].filter(Boolean).join('\n\n');r.source='Combined request context';r.reviewed=false;const overlay=document.createElement('div');overlay.className='workflow-loading';overlay.setAttribute('role','status');overlay.innerHTML='<span class="workflow-spinner"></span><div><b>Preparing SRS…</b><p>Combining your text, documents and meeting context</p></div>';document.body.appendChild(overlay);setTimeout(()=>{try{if(selected!==id)return;sectionDrafts[id]=['Draft SRS for '+appProject().name+'\n\n'+content,'Source context\n\n'+content,'Functional requirements\n\nReview the combined source context and define the functional requirements. Automated AI synthesis is not connected.','Non-functional requirements\n\nTo be confirmed from the supplied context.','Business rules\n\nTo be confirmed from the supplied context.','Assumptions & constraints\n\nThis draft combines the supplied sources. AI synthesis is not connected.\n'+d.files.filter(f=>!f.text.trim()).map(f=>'Attachment not analyzed: '+f.name).join('\n'),'Glossary\n\nSRS — Software Requirements Specification'];for(let i=0;i<7;i++)delete richSections[id+':'+i];sectionIndex=0;jumpPage('srs');}finally{overlay.remove();}},850);};
Object.assign(localizedLabels,{'Combine text, documents and meeting context. Use any one source or all three.':'テキスト、文書、会議の内容を組み合わせます。どれか1つだけでも利用できます。','Optional':'任意','Added':'追加済み','All added sources will be combined. Switching tabs keeps your data in this session.':'追加したすべての情報を統合します。タブを切り替えても、このセッションのデータは保持されます。','Add supporting files':'参考ファイルを追加','Meeting notes or transcript':'会議メモまたは文字起こし','Transcript will appear here.':'文字起こしがここに表示されます。'});
render();
// Keep the original visual designs inside the shared request tabs.
const combinedRequestPage = blueprintPageRoutes.request;
blueprintPageRoutes.request=function(){let html=combinedRequestPage();const start=html.indexOf('<div class="context-tabs"'),end=html.indexOf('<div class="context-content"',start);if(start<0)return html;const d=requestDraft();const cards='<div class="input-options restored-input-tabs" role="tablist">'+[['text','requirements','Text input','Describe your idea in your own words.'],['upload','projects','Upload documents','Add supporting files to your requirements.'],['meeting','teams','Meeting recording','Record meeting audio for transcription and translation.']].map(([key,i,title,description])=>'<button role="tab" aria-selected="'+(d.tab===key)+'" class="input-option '+(d.tab===key?'selected':'')+'" onclick="contextTab(\''+key+'\')"><span class="input-icon">'+icon(i)+'</span><b>'+title+'</b><small>'+description+'</small></button>').join('')+'</div>';return html.slice(0,start)+cards+html.slice(end);};
function meetingDraft(){const d=requestDraft();return d.google ||= {count:0,playing:false,timer:null,language:'en-ja'};}
contextMeeting=function(){const d=requestDraft(),g=meetingDraft();let content='';if(d.meetingType==='google'){const previous={count:livePreview.count,playing:livePreview.playing,link:meetLinkValue,language:meetingLanguage};try{livePreview.count=g.count;livePreview.playing=g.playing;meetLinkValue=d.link;meetingLanguage=g.language;content=liveMeetingPage().slice(appNav().length).replaceAll('meetLinkValue=this.value','requestDraft().link=this.value').replaceAll('meetingLanguage=this.value;render()','meetingDraft().language=this.value;render()').replaceAll('playLivePreview()','playContextGoogle()').replaceAll('resetLivePreview()','resetContextGoogle()').replace('<div class="call-controls">','<div class="call-controls"><button class="request-stop" '+(g.playing?'':'disabled')+' onclick="stopContextZoom()">■ Stop meeting</button>').replaceAll('addLiveContext()','keepMeetingContext()');}finally{livePreview.count=previous.count;livePreview.playing=previous.playing;meetLinkValue=previous.link;meetingLanguage=previous.language;}}else{content=bpHeading(esc(d.title||'Product requirements discussion'),'Demo transcript · Speakers are sample participants.',(d.running?'':button('New recording','setupContextMeeting()'))+'<button class="request-stop" '+(d.running?'':'disabled')+' onclick="stopContextMeeting()">■ Stop recording</button>')+'<div class="notice">'+(d.running?'● Demo recording in progress':d.entries.length?'Demo recording finished':'Ready to record')+' · Sample transcript and translation, not captured audio.</div>'+contextTranscripts(d);}return '<div class="context-meeting-tabs" role="tablist">'+[['recording','Record a meeting'],['google','Zoom meeting']].map(([key,title])=>'<button role="tab" aria-selected="'+(d.meetingType===key)+'" class="'+(d.meetingType===key?'primary':'')+'" onclick="contextMeetingType(\''+key+'\')">'+title+'</button>').join('')+'</div><div class="restored-meeting">'+content+'</div>';};
setupContextMeeting=function(){newRecordingSetup();};
const standaloneRecordingStart=startDemoRecording;
startDemoRecording=function(){if(screen!=='request')return standaloneRecordingStart();requestDraft().title=document.getElementById('recordTitle').value.trim()||'Product requirements discussion';startContextMeeting();};
function playContextGoogle(){const id=selected,g=meetingDraft();if(g.playing){clearInterval(g.timer);g.playing=false;render();return;}if(g.count>=jpMeeting.length)g.count=0;g.playing=true;g.count++;g.timer=setInterval(()=>{g.count++;if(g.count>=jpMeeting.length){g.playing=false;clearInterval(g.timer);}if(selected===id&&screen==='request'&&requestDraft().tab==='meeting'&&requestDraft().meetingType==='google'){captureReq();render();}},1800);render();}
function resetContextGoogle(){const g=meetingDraft();clearInterval(g.timer);g.playing=false;g.count=0;render();}
function keepMeetingContext(){toast('Meeting context is included. Continue to SRS when your inputs are ready.');}
const combineRecordingContext=combinedRequestContext;
combinedRequestContext=function(r,d){const base=combineRecordingContext(r,d),google=d.google?.count?jpMeeting.slice(0,d.google.count).map(row=>row[0]+': '+row[1]+'\n'+row[2]).join('\n\n'):'';return [base,google?'Zoom transcript · Demo\n'+google:''].filter(Boolean).join('\n\n');};
render();

// Keep capture controls available while the user adds text or files.
function stopContextZoom(){const g=meetingDraft();clearInterval(g.timer);g.timer=null;g.playing=false;captureReq();render();toast('Meeting preview stopped. Your transcript is kept.');}
const requestPageWithCapture=blueprintPageRoutes.request;
blueprintPageRoutes.request=function(){
 let html=requestPageWithCapture();if(!selected)return html;
 const d=requestDraft(),g=meetingDraft();
 const active=d.running||g.playing;
 const status=active?'<div class="request-capture-status" role="status"><div><span class="capture-dot"></span><strong>Capture preview running</strong><small>You can keep adding text and files.</small></div><div class="actions">'+(d.running?'<button class="request-stop" onclick="stopContextMeeting()">■ Stop recording</button>':'')+(g.playing?'<button class="request-stop" onclick="stopContextZoom()">■ Stop meeting</button>':'')+'</div></div>':'';
 html=html.replace('<div class="context-content"',status+'<div class="context-content"');
 html=html.replace('All added sources will be combined. Switching tabs keeps your data in this session.','Use any combination of inputs. Your text, files and transcript stay together.');
 return html;
};
Object.assign(localizedLabels,{
 '■ Stop recording':'■ 録音を停止','■ Stop meeting':'■ 会議を停止',
 'Capture preview running':'収録プレビュー中','You can keep adding text and files.':'テキストやファイルを引き続き追加できます。',
 'Meeting preview stopped. Your transcript is kept.':'会議プレビューを停止しました。文字起こしは保持されます。',
 'Use any combination of inputs. Your text, files and transcript stay together.':'入力方法は自由に組み合わせられます。テキスト、ファイル、文字起こしはまとめて保持されます。'
});
render();
